#!/usr/bin/env python3
"""Offline model/binding-table compiler. Application PDU only; no BLE or product branches."""
from __future__ import annotations
import argparse, copy, csv, hashlib, io, json, math, re, struct, subprocess, sys
from decimal import Decimal, InvalidOperation
from pathlib import Path

FORMAT = 'ble-model-mapping/0.2'
MAX_PDU, MAX_DEPTH = 2048, 5
NUM = {'u8':('B',1),'u16':('H',2),'u32':('I',4),'i8':('b',1),'i16':('h',2),'i32':('i',4),'f32':('f',4),'f64':('d',8)}
CONTAINERS = {'array','object','group','repeated_object'}
ROLES = {'request','incoming'}
COMMAND_COLUMNS = ['operation','method','sid','cid','interaction','receive_variants','correlation','timeout_ms','source','availability']
BINDING_COLUMNS = ['operation','role','tlv_path','model_path','wire_type','required','scale','offset','max_bytes']
GROUP_COLUMNS = ['operation','role','container_path','rule','fields']

class MappingError(ValueError):
    def __init__(self, code, message): super().__init__(message); self.code=code

def require(ok, code, message):
    if not ok: raise MappingError(code,message)

def number(s, default):
    try: n=Decimal(str(s if s not in ('',None) else default))
    except InvalidOperation: raise MappingError('DICTIONARY_INVALID','Invalid decimal')
    require(n.is_finite(),'DICTIONARY_INVALID','Nonfinite decimal');return n

# JSON value shape and platform storage type are independent of the BLE wire type.
PLATFORM_TYPES = {'object':'object','array':'array','Int32':'integer',
                  'Float':'number','Double':'number','Bool':'boolean','String':'string'}

def check_platform_schema(schema):
    if 'platformType' not in schema: return  # Legacy shape is not a guessed storage type.
    platform = schema['platformType']
    require(isinstance(platform,str), 'MODEL_SCHEMA', 'platformType必须为受支持的字符串')
    expected = {'integer','string'} if platform == 'Enum' else {PLATFORM_TYPES.get(platform)}
    require(platform in {*PLATFORM_TYPES, 'Enum'} and schema.get('type') in expected,
            'MODEL_SCHEMA', 'platformType与JSON type不一致或平台类型未受支持')
    if platform == 'Enum':
        values = schema.get('enum')
        require(isinstance(values,list) and values, 'MODEL_SCHEMA', 'Enum必须声明非空枚举值集合')
        require(all(type(v) is (int if schema['type']=='integer' else str) for v in values),
                'MODEL_SCHEMA', 'Enum值必须是同类型的整数或字符串')
    # Validate intrinsic domains without injecting a full Int32 range into u8 bindings.
    for key in ['minimum','maximum']:
        if key in schema and platform in {'Int32','Float','Double'}:
            check_platform_value(platform, schema[key], 'MODEL_SCHEMA')
    if 'minimum' in schema and 'maximum' in schema:
        require(schema['minimum'] <= schema['maximum'], 'MODEL_SCHEMA', '最小值不能大于最大值')
    for value in schema.get('enum', []):
        check_platform_value('Int32' if platform=='Enum' and schema['type']=='integer' else platform,
                             value, 'MODEL_SCHEMA')

def check_platform_value(platform, value, code='MODEL_CONSTRAINT'):
    if platform == 'Int32':
        require(type(value) in (int,float) and -2147483648 <= value <= 2147483647
                and int(value)==value, code, 'Int32须为有符号32位整数')
    elif platform in {'Float','Double'}:
        require(type(value) in (int,float), code, platform+'须为有限数值')
        try:
            converted = float(value)
            stored = struct.unpack('>f',struct.pack('>f',converted))[0] if platform=='Float' else converted
        except (OverflowError, struct.error):
            raise MappingError(code, platform+'超出存储范围')
        require(math.isfinite(stored) and (value==0 or stored!=0), code,
                platform+'溢出或非零值下溢为0')
        # Keep the engineering JSON value. Storage rounding is explicit consumer work;
        # never quantize before range/step checks or integer-wire inverse conversion.
    elif platform == 'Bool': require(type(value) is bool, code, 'Bool须为JSON布尔值')
    elif platform == 'String': require(isinstance(value,str), code, 'String须为JSON字符串')

def validate_model(schema, data):
    try:
        from jsonschema import Draft202012Validator, validators
        from jsonschema.exceptions import ValidationError
    except ImportError: raise MappingError('DEPENDENCY_MISSING','Install examples/app-protocol-mapping-v1/requirements.txt in an isolated Python environment')
    def exact_multiple(validator,divisor,instance,schema):
        if type(instance) not in (int,float):return
        value=Decimal(str(instance));step=Decimal(str(divisor))
        if not value.is_finite() or not step.is_finite() or step<=0 or value/step!=(value/step).to_integral_value():yield ValidationError('Value is not an exact multiple of '+str(divisor))
    def platform_value(validator,platform,instance,schema):
        try:
            check_platform_value('Int32' if platform=='Enum' and schema.get('type')=='integer' else platform, instance)
        except MappingError as error: yield ValidationError(str(error))
    exact=validators.extend(Draft202012Validator,{'multipleOf':exact_multiple,'platformType':platform_value})
    errors=sorted(exact(schema).iter_errors(data), key=lambda e:str(list(e.path)))
    if errors: raise MappingError('MODEL_CONSTRAINT',str(list(errors[0].path))+': '+errors[0].message)

def platform_json_value(schema, data):
    """After validation, keep floating JSON numbers for explicit Float/Double nodes.

    This is not Float storage quantization. Legacy nodes keep their existing result.
    """
    if schema.get('type')=='object':
        return {k:platform_json_value(schema['properties'][k],v) for k,v in data.items()}
    if schema.get('type')=='array': return [platform_json_value(schema['items'],v) for v in data]
    if schema.get('platformType') in {'Float','Double'}: return float(data)
    if schema.get('platformType')=='Int32': return int(data)
    return data

def source_bytes(path):
    return subprocess.check_output(['/bin/cat',str(path)]) if sys.platform=='darwin' else Path(path).read_bytes()

def read_rows(path, columns):
    # Use the project's established stream-read path on the local Mac volume.
    # UTF-8 validation remains strict; bytes are never repaired or reinterpreted.
    raw=source_bytes(path)
    try: text=raw.decode('utf-8-sig',errors='strict')
    except UnicodeError: raise MappingError('CSV_ENCODING','CSV must be valid UTF-8')
    r=csv.DictReader(io.StringIO(text,newline=''));legacy = columns == COMMAND_COLUMNS and r.fieldnames == COMMAND_COLUMNS[:-1]
    require(r.fieldnames==columns or legacy,'CSV_HEADER',str(path)+' columns mismatch');rows=list(r)
    if legacy:
        for row in rows: row['availability']='active'
    require(all(None not in x and all(v is not None for v in x.values()) for x in rows),'CSV_SHAPE','Invalid CSV row')
    return rows

def path_parts(path):
    parts=path.split('/')
    require(all(re.fullmatch(r'(?:0x)?[0-9a-fA-F]{1,2}',x) for x in parts),'ADDRESS_INVALID','Use logical hexadecimal TLV path')
    out=tuple(int(x,16) for x in parts);require(all(0<=x<=127 for x in out),'ADDRESS_INVALID','Use logical Type without the container flag');require(all(x<124 for x in out),'ADDRESS_RESERVED','Type7C..7E are common security fields; Type7F is the fixed result component');return out

def schema_at(schema, path):
    current=schema
    for token in path.split('.') if path else []:
        m=re.fullmatch(r'([A-Za-z_][A-Za-z0-9_]*)(\[\])?',token)
        require(m is not None,'MODEL_PATH','Invalid model path '+path)
        require(current.get('type')=='object' and m[1] in current.get('properties',{}),'MODEL_PATH','Missing model node '+path)
        current=current['properties'][m[1]]
        if m[2]:
            require(current.get('type')=='array','MODEL_PATH','[] requires an array');current=current['items']
    return current

def role_schema(model, command, role):
    method=model['methods'][command['method']]
    return method['input'] if role=='request' else method['output']

def length_encode(n):
    require(type(n) is int and 0<=n<=16383,'LENGTH_RANGE','Length must be0..16383')
    return bytes([n]) if n<128 else bytes([0x80|(n>>7),n&127])

def length_decode(buf,pos):
    require(pos<len(buf),'LENGTH_TRUNCATED','Missing Length');a=buf[pos];pos+=1
    if a<128:return a,pos
    require(pos<len(buf),'LENGTH_TRUNCATED','Missing second Length byte');b=buf[pos];pos+=1
    require(b<128,'LENGTH_CONTINUATION','Third Length byte is unsupported');n=((a&127)<<7)|b
    require(n>=128,'LENGTH_NONCANONICAL','Two-byte Length requires128..16383');return n,pos

def decimal_value(v):
    require(type(v) in (int,float),'VALUE_TYPE','Numeric value required')
    require(not isinstance(v,float) or math.isfinite(v),'VALUE_TYPE','Finite value required');return Decimal(str(v))

def scalar_encode(node,value):
    t=node['wire_type'];packed=t.endswith('[]');base=t[:-2] if packed else t
    if packed:
        require(isinstance(value,list) and base in NUM,'VALUE_TYPE','Packed array requires fixed-width numeric elements')
        return b''.join(scalar_encode({**node,'wire_type':base},v) for v in value)
    if base in NUM:
        raw=(decimal_value(value)-number(node['offset'],0))/number(node['scale'],1)
        raw_nonzero=raw!=0
        if base[0] in 'ui':require(raw==raw.to_integral_value(),'VALUE_EXACT','Do not round illegal engineering values');raw=int(raw)
        else:raw=float(raw)
        try: out=struct.pack('>'+NUM[base][0],raw)
        except (struct.error,OverflowError):raise MappingError('VALUE_RANGE','Value outside '+base)
        if base[0]=='f':
            stored=struct.unpack('>'+NUM[base][0],out)[0]
            require(math.isfinite(stored) and (not raw_nonzero or stored!=0),'VALUE_RANGE','Float overflow or nonzero underflow')
        return out
    if base=='bool':require(type(value) is bool,'VALUE_TYPE','Strict boolean required');return bytes([int(value)])
    if base=='utf8':
        require(isinstance(value,str),'VALUE_TYPE','String required')
        try:out=value.encode('utf-8',errors='strict')
        except UnicodeError:raise MappingError('VALUE_UTF8','Invalid UTF-8 input')
    elif base=='bytes':
        require(isinstance(value,str) and re.fullmatch(r'(?:[0-9a-fA-F]{2})*',value) is not None,'VALUE_TYPE','Bytes must be even-length hexadecimal');out=bytes.fromhex(value)
    else:raise MappingError('WIRE_TYPE','Unsupported wire type '+base)
    if node['max_bytes'] is not None:require(len(out)<=node['max_bytes'],'VALUE_LENGTH','Value exceeds declared byte limit')
    return out

def scalar_decode(node,buf):
    t=node['wire_type'];packed=t.endswith('[]');base=t[:-2] if packed else t
    if packed:
        width=NUM[base][1];require(len(buf)%width==0,'VALUE_WIDTH','Packed array length is not a multiple of element width')
        return [scalar_decode({**node,'wire_type':base},buf[i:i+width]) for i in range(0,len(buf),width)]
    if base in NUM:
        require(len(buf)==NUM[base][1],'VALUE_WIDTH','Wrong fixed-width scalar length');raw=struct.unpack('>'+NUM[base][0],buf)[0]
        require(not isinstance(raw,float) or math.isfinite(raw),'VALUE_RANGE','Nonfinite wire value');v=Decimal(str(raw))*number(node['scale'],1)+number(node['offset'],0)
        result=int(v) if v==v.to_integral_value() else float(v)
        require(not isinstance(result,float) or (math.isfinite(result) and (v==0 or result!=0)),
                'VALUE_RANGE','Engineering value overflow or nonzero underflow')
        return result
    if base=='bool':require(buf in (b'\0',b'\1'),'VALUE_TYPE','Invalid wire boolean');return bool(buf[0])
    if base=='bytes':out=buf.hex().upper()
    elif base=='utf8':
        try:out=buf.decode('utf-8',errors='strict')
        except UnicodeError:raise MappingError('VALUE_UTF8','Invalid UTF-8')
    else:raise MappingError('WIRE_TYPE','Unsupported wire type')
    scalar_encode(node,out);return out

def check_groups(node,data):
    for group in node.get('groups',[]):
        count=sum(name in data for name in group['fields'])
        if group['rule']=='at_least_one':require(count>0,'FIELD_GROUP','At least one of '+','.join(group['fields']))
        else:require(count in (0,len(group['fields'])),'FIELD_GROUP','All or none of '+','.join(group['fields']))

def projected_keys(nodes):
    out=[]
    for n in nodes:
        if n['wire_type']=='group':out.extend(projected_keys(n['children']))
        elif n['key'] is not None:out.append(n['key'])
    return out

def encode_nodes(nodes,data,depth=1):
    require(depth<=MAX_DEPTH,'NESTING_LIMIT','TLV nesting exceeds limit')
    require(isinstance(data,dict),'VALUE_TYPE','Object expected')
    allowed=set(projected_keys(nodes))
    require(not(set(data)-allowed),'FIELD_NOT_BOUND','Unmapped business input fields')
    out=bytearray()
    for n in nodes:
        if n['wire_type']=='group':
            value={k:v for k,v in data.items() if k in projected_keys(n['children'])}
            if not value and not n['required']:continue
        else:
            if n['key'] not in data:require(not n['required'],'FIELD_REQUIRED','Missing '+str(n['model_path']));continue
            value=data[n['key']]
        if n['wire_type']=='repeated_object':
            require(isinstance(value,list),'VALUE_TYPE','Repeated objects require array data')
            out.extend(b''.join(encode_node(n,item,depth) for item in value));continue
        if n['wire_type']=='array':
            require(isinstance(value,list),'VALUE_TYPE','Array expected');item=n['children'][0];payload=b''.join(encode_node(item,v,depth+1) for v in value)
        else:payload=encode_content(n,value,depth)
        out.extend(bytes([n['type_id']|(128 if n['wire_type'] in CONTAINERS else 0)])+length_encode(len(payload))+payload)
    return bytes(out)

def encode_content(n,value,depth):
    if n['wire_type'] in {'object','group','repeated_object'}:
        check_groups(n,value);return encode_nodes(n['children'],value,depth+1)
    return scalar_encode(n,value)

def encode_node(n,value,depth):
    require(depth<=MAX_DEPTH,'NESTING_LIMIT','TLV nesting exceeds limit');payload=encode_content(n,value,depth)
    return bytes([n['type_id']|(128 if n['wire_type'] in CONTAINERS else 0)])+length_encode(len(payload))+payload

def read_tlvs(buf):
    pos=0
    while pos<len(buf):
        wire=buf[pos];pos+=1;n,pos=length_decode(buf,pos);require(pos+n<=len(buf),'TLV_BOUNDARY','Value exceeds enclosing TLV/PDU')
        yield wire,buf[pos:pos+n];pos+=n

def decode_content(n,payload,depth):
    require(depth<=MAX_DEPTH,'NESTING_LIMIT','TLV nesting exceeds limit')
    if n['wire_type']=='array':
        item=n['children'][0];out=[]
        for wire,b in read_tlvs(payload):
            require(wire&127==item['type_id'],'UNKNOWN_TYPE','Unknown array item Type')
            check_flag(item,wire,b);out.append(decode_content(item,b,depth+1))
        return out
    if n['wire_type'] in {'object','group','repeated_object'}:
        value=decode_nodes(n['children'],payload,depth+1);check_groups(n,value);return value
    return scalar_decode(n,payload)

def check_flag(n,wire,payload):
    container=n['wire_type'] in CONTAINERS
    # Existing application grammar permits either flag on an empty extensible container.
    require(bool(wire&128)==container or (container and not payload),'CONTAINER_FLAG','Type container flag mismatch')

def decode_nodes(nodes,buf,depth=1):
    table={n['type_id']:n for n in nodes};out={};seen=set()
    for wire,b in read_tlvs(buf):
        tid=wire&127;require(tid in table,'UNKNOWN_TYPE','Unknown Type in configured scope');n=table[tid];require(tid not in seen or n['wire_type']=='repeated_object','DUPLICATE_TYPE','Duplicate nonrepeated Type');seen.add(tid);check_flag(n,wire,b);v=decode_content(n,b,depth)
        if n['wire_type']=='repeated_object':out.setdefault(n['key'],[]).append(v);continue
        if n['wire_type']=='group':require(not(set(out)&set(v)),'MODEL_PATH','Wrapper path collision');out.update(v)
        else:out[n['key']]=v
    for n in nodes:require(not n['required'] or n['type_id'] in seen,'FIELD_REQUIRED','Missing '+n['model_path'])
    return out

def compile_tables(folder):
    folder=Path(folder);model=json.loads((folder/'thing-model.json').read_text());identity=json.loads((folder/'product.system.json').read_text());commands={};addresses=set()
    require(all(isinstance(identity.get(k),str) and identity[k] for k in ['product_id','firmware_version','function_version','dictionary_version','transport_ref']),'IDENTITY_REQUIRED','System identity is incomplete')
    for row in read_rows(folder/'commands.csv',COMMAND_COLUMNS):
        require(row['operation'] and row['operation'] not in commands,'COMMAND_DUPLICATE','Operation must be unique');sid,cid=int(row['sid'],16),int(row['cid'],16)
        require(16<=sid<=254 and 0<=cid<=255,'PUBLIC_SERVICE_FIXED','Business dictionary requires SID10..7F (category extension) or SID80..FE (temporary custom/experimental); SID00, SID01..0F and SIDFF are excluded; CID must be one byte')
        require((sid,cid) not in addresses,'ADDRESS_CONFLICT','Same product address has two definitions');addresses.add((sid,cid))
        require(row['method'] in model.get('methods',{}),'MODEL_PATH','Method is absent from thing model')
        require(row['interaction'] in {'request_response','query_and_report','one_way','receive_only'},'INTERACTION_INVALID','Unknown interaction')
        row['availability'] = row.get('availability') or 'active'
        require(row['availability'] in {'active','suspended'},'AVAILABILITY_INVALID','Availability must be active or suspended')
        require(row['correlation'] in {'unmarked','none'},'INTERACTION_INVALID','Only source unmarked/one-way supported in this review engine')
        variants=row['receive_variants'].split('|') if row['receive_variants'] else []
        require(set(variants)<={'incoming','result','empty'},'INTERACTION_INVALID','Unknown receive variant')
        timeout=None if not row['timeout_ms'] else int(row['timeout_ms']);require(timeout is None or timeout>0,'TIMING_INVALID','Timeout must be positive or unconfirmed')
        if row['interaction']=='one_way':require(not variants,'INTERACTION_INVALID','One-way cannot invent replies')
        commands[row['operation']]={**row,'sid':sid,'cid':cid,'receive_variants':variants,'timeout_ms':timeout,'result_component':'R3.common_u32_7f' if 'result' in variants else None,'layouts':{}}
        input_schema=model['methods'][row['method']]['input']
        if row['interaction']!='receive_only' and input_schema.get('type')=='object' and input_schema.get('properties')=={} and input_schema.get('additionalProperties') is False:commands[row['operation']]['layouts']['request']=[]
    rows=read_rows(folder/'bindings.csv',BINDING_COLUMNS);trees={}
    for row in sorted(rows,key=lambda x:len(path_parts(x['tlv_path']))):
        op,role=row['operation'],row['role'];require(op in commands and role in ROLES,'DIRECTION_INVALID','Unknown operation or role');cmd=commands[op];path=path_parts(row['tlv_path']);require(len(path)<=MAX_DEPTH,'NESTING_LIMIT','Mapping too deep');key=(op,role);lookup=trees.setdefault(key,{})
        require(path not in lookup,'ADDRESS_CONFLICT','Duplicate TLV path');parent=lookup.get(path[:-1]);require(len(path)==1 or parent is not None,'PATH_PARENT','Declare parent containers')
        if parent:require(parent['wire_type'] in CONTAINERS,'PATH_PARENT','Leaf cannot contain children')
        root_schema=role_schema(model,cmd,role);node_schema=schema_at(root_schema,row['model_path']);wire_type=row['wire_type'];base=wire_type[:-2] if wire_type.endswith('[]') else wire_type
        require(wire_type in CONTAINERS or base in NUM or base in {'bool','utf8','bytes'},'WIRE_TYPE','Unsupported wire type')
        require(not wire_type.endswith('[]') or base in NUM,'WIRE_TYPE','Packed arrays must use numeric fixed-width elements')
        prefix=parent['model_path']+('[]' if parent['wire_type']=='repeated_object' else '') if parent else ''
        is_item=bool(parent and parent['wire_type']=='array')
        if is_item:
            require(row['model_path']==prefix+'[]' and wire_type=='object','MODEL_PATH','Array child must map its object item');local_key=None
        elif wire_type=='group':require(row['model_path']==prefix,'MODEL_PATH','Wrapper must share business scope');local_key=None
        else:
            local_key=row['model_path'][len(prefix)+1:] if prefix else row['model_path'];require(not prefix or row['model_path'].startswith(prefix+'.'),'MODEL_PATH','Child leaves parent model scope');require(re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*',local_key) is not None,'MODEL_PATH','Bind all intermediate business containers')
        if wire_type in CONTAINERS:require(node_schema.get('type')==('array' if wire_type in {'array','repeated_object'} else 'object'),'TYPE_MISMATCH','Container/model mismatch')
        elif wire_type.endswith('[]'):require(node_schema.get('type')=='array' and node_schema['items'].get('type') in {'integer','number'},'TYPE_MISMATCH','Packed array/model mismatch')
        else:require(node_schema.get('type') in ({'integer','number'} if base in NUM else {'boolean'} if base=='bool' else {'string'}),'TYPE_MISMATCH','Leaf/model mismatch')
        require(row['required'] in {'M','O'},'CSV_VALUE','Required must be M/O');scale=number(row['scale'],1);offset=number(row['offset'],0);require(scale!=0,'CSV_VALUE','Scale cannot be zero')
        require(base in NUM or (scale==1 and offset==0),'TYPE_MISMATCH','Non-numeric type cannot use scaling')
        maximum=None if not row['max_bytes'] else int(row['max_bytes']);require(maximum is None or 0<maximum<=16383,'VALUE_LENGTH','Invalid byte bound')
        node={'type_id':path[-1],'model_path':row['model_path'],'key':local_key,'wire_type':wire_type,'required':row['required']=='M','scale':str(scale),'offset':str(offset),'max_bytes':maximum,'children':[],'groups':[]};lookup[path]=node
        if parent:parent['children'].append(node)
        else:cmd['layouts'].setdefault(role,[]).append(node)
    for row in read_rows(folder/'groups.csv',GROUP_COLUMNS):
        key=(row['operation'],row['role']);node=trees.get(key,{}).get(path_parts(row['container_path']));require(node is not None and node['wire_type'] in {'object','group'},'GROUP_INVALID','Group requires object scope');names=row['fields'].split('|');require(row['rule'] in {'at_least_one','all_or_none'} and len(names)==len(set(names)) and names,'GROUP_INVALID','Invalid field group');require(set(names)<={n['key'] for n in node['children']},'GROUP_INVALID','Group references unbound field');node['groups'].append({'rule':row['rule'],'fields':names})
    for op,cmd in commands.items():
        require(('request' in cmd['layouts'])==(cmd['interaction']!='receive_only'),'DIRECTION_INVALID','Request layout must match interaction')
        if cmd['interaction']=='receive_only':require(cmd['receive_variants']==['incoming'],'DIRECTION_INVALID','Receive-only must have exactly incoming data')
        require(('incoming' in cmd['layouts'])==('incoming' in cmd['receive_variants']),'DIRECTION_INVALID','Incoming layout/variant mismatch')
    for lookup in trees.values():
        for node in lookup.values():
            if node['wire_type']=='array':require(len(node['children'])==1 and node['children'][0]['key'] is None,'MODEL_PATH','Array has exactly one repeated item mapping')
            if node['wire_type'] not in CONTAINERS:require(not node['children'],'PATH_PARENT','Leaf children not allowed')
    snapshot={'format_version':FORMAT,'identity':identity,'thing_model':model,'commands':commands,'source_files':{n:hashlib.sha256(source_bytes(folder/n)).hexdigest() for n in ['thing-model.json','product.system.json','commands.csv','bindings.csv','groups.csv']}}
    check_snapshot(snapshot,identity)
    return snapshot

def check_schema_subset(schema):
    allowed={'type','platformType','properties','items','required','additionalProperties','minimum','maximum','multipleOf','enum','minItems','maxItems','minLength','maxLength','title','description','format','access'}
    require(isinstance(schema,dict) and not(set(schema)-allowed),'MODEL_SCHEMA','Unsupported model schema keyword')
    require(schema.get('type') in {'object','array','integer','number','boolean','string'},'MODEL_SCHEMA','Unsupported model type')
    check_platform_schema(schema)
    if 'access' in schema:require(schema['access'] in {'r','w','rw'},'PROPERTY_ACCESS','access must be r, w or rw')
    if 'format' in schema:require(schema['format']=='hex','MODEL_SCHEMA','Only explicit hex bytes format is supported')
    if schema['type']=='object':
        require(schema.get('additionalProperties') is False and isinstance(schema.get('properties'),dict),'MODEL_SCHEMA','Declare a closed business object')
        require(set(schema.get('required',[]))<=set(schema['properties']),'MODEL_SCHEMA','Unknown required business field')
        for name,child in schema['properties'].items():
            require(re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*',name) is not None,'MODEL_SCHEMA','Model identifiers cannot contain path delimiters');check_schema_subset(child)
    if schema['type']=='array':require('items' in schema,'MODEL_SCHEMA','Array needs item schema');check_schema_subset(schema['items'])

def check_tree(nodes,schema,depth=1,prefix='',item_scope=False):
