"""Two user-facing files: business model and flat BLE address mappings.

This adapter only prepares data for the shared codec; it adds no wire protocol.
"""
import copy
import hashlib
import json
from decimal import Decimal
from pathlib import Path
import ble_protocol_mapping as codec

FORMAT = "ble-thing-mapping/1"
CAPABILITIES = {"model-reference/1", "property-updates/1", "nested-tlv/1", "receive-only/1", "repeated-object/1", "result-success-code/1", "numeric-defaults/1", "tlv-length-1-2/1", "platform-types/1"}
MODEL_METADATA = {"format", "id", "name", "version", "description", "schema_dialect", "numeric_step_defaults", "notes"}
COMMAND_METADATA = {"propertyUpdates", "resultSuccessCode", "notes"}


def has_platform_types(model):
    def has_platform_type(node):
        if not isinstance(node, dict): return False
        return "platformType" in node or any(has_platform_type(n) for n in node.get("properties", {}).values()) or has_platform_type(node.get("items"))
    nodes = list(model.get("properties", {}).values()) + list(model.get("events", {}).values())
    nodes += [service[role] for service in model.get("services", model.get("methods", {})).values() for role in ["input", "output"]]
    return any(has_platform_type(node) for node in nodes)


def required_capabilities(model, mapping):
    capabilities = {"model-reference/1", "tlv-length-1-2/1"}
    if has_platform_types(model): capabilities.add("platform-types/1")
    if "numeric_step_defaults" in model: capabilities.add("numeric-defaults/1")
    for command in mapping["commands"]:
        if command.get("propertyUpdates"): capabilities.add("property-updates/1")
        if "resultSuccessCode" in command: capabilities.add("result-success-code/1")
        if command.get("interaction") == "receive_only": capabilities.add("receive-only/1")
        for field in command.get("request", []) + command.get("incoming", []):
            if field.get("wireType") in codec.CONTAINERS: capabilities.add("nested-tlv/1")
            if field.get("wireType") == "repeated_object": capabilities.add("repeated-object/1")
    return capabilities


def validate_schema(value, name, code):
    from jsonschema import Draft202012Validator
    schema = json.loads(codec.source_bytes(Path(__file__).resolve().parents[1] / "supporting" / name))
    errors = sorted(Draft202012Validator(schema).iter_errors(value), key=lambda e: str(list(e.path)))
    if errors:
        error = errors[0]
        path = "/" + "/".join(str(x) for x in error.path)
        require(False, code, f"{path}：{error.message}")


def json_text(value):
    return json.dumps(value, ensure_ascii=False, indent=2, allow_nan=False) + "\n"


def model_hash(model):
    """Content hash v1: sorted keys, JSON strings, expanded decimal numbers."""
    def canonical(value):
        if value is None: return "null"
        if type(value) is bool: return "true" if value else "false"
        if isinstance(value, str): return json.dumps(value, ensure_ascii=False)
        if type(value) in {int, float}:
            number = Decimal(str(value))
            require(number.is_finite(), "MODEL_SCHEMA", "物模型不能包含非有限数")
            text = format(number, "f")
            text = text.rstrip("0").rstrip(".") if "." in text else text
            return "0" if number == 0 else text
        if isinstance(value, list): return "[" + ",".join(canonical(x) for x in value) + "]"
        require(isinstance(value, dict) and all(isinstance(k, str) for k in value), "MODEL_SCHEMA", "物模型只允许JSON值")
        return "{" + ",".join(canonical(k) + ":" + canonical(value[k]) for k in sorted(value)) + "}"
    return hashlib.sha256(canonical(model).encode("utf-8")).hexdigest()


def model_metadata(model):
    return {k: copy.deepcopy(model[k]) for k in MODEL_METADATA if k in model}


def apply_numeric_defaults(schema, defaults):
    if schema.get("type") in {"integer", "number"} and "multipleOf" not in schema:
        schema["multipleOf"] = defaults[schema["type"]]
    for child in schema.get("properties", {}).values():
        apply_numeric_defaults(child, defaults)
    if "items" in schema:
        apply_numeric_defaults(schema["items"], defaults)


def require(ok, code, message):
    codec.require(ok, code, message)


def normalize_model(model):
    require(isinstance(model, dict), "MODEL_SCHEMA", "物模型必须是JSON对象")
    model = copy.deepcopy(model)
    require(not ("methods" in model and "services" in model), "MODEL_SCHEMA", "services与旧methods不能同时声明")
    if "services" in model:
        model["methods"] = model.pop("services")
    require({"properties", "methods", "events"} <= set(model), "MODEL_SCHEMA", "物模型必须包含properties、services、events")
    validate_schema(public_model(model), "thing-model-definition.schema.json", "MODEL_SCHEMA")
    for key in MODEL_METADATA:
        model.pop(key, None)
    require(set(model) == {"properties", "methods", "events"}, "MODEL_SCHEMA", "物模型必须包含properties、services、events；兼容旧methods名称")
    return model


def public_model(model):
    model = copy.deepcopy(model)
    model["services"] = model.pop("methods")
    return model


def object_schema(properties=None):
    properties = properties or {}
    return {"type": "object", "properties": properties, "required": list(properties), "additionalProperties": False}


def target_reference(target):
    parts = [target["kind"], target["identifier"]]
    if target["kind"] == "property":
        parts.append(target.get("behavior", ""))
    return ":".join(parts)


def row_target(row):
    reference = row["method"]
    if ":" not in reference:
        return {"kind": "service", "identifier": reference}
    parts = reference.split(":")
    require((len(parts) == 3 and parts[0] == "property") or (len(parts) == 2 and parts[0] in {"service", "event"}), "MAPPING_TARGET", "功能引用应为property:名称:read/write/report、service:名称或event:名称")
    target = {"kind": parts[0], "identifier": parts[1]}
    if len(parts) == 3:
        target["behavior"] = parts[2]
    return target


def prepare(workspace):
    """Create internal service adapters without adding services to the public model."""
    effective = copy.deepcopy(workspace)
    defaults = workspace.get("model_metadata", {}).get("numeric_step_defaults")
    if defaults:
        for schema in effective["model"]["properties"].values():
            apply_numeric_defaults(schema, defaults)
        for service in effective["model"]["methods"].values():
            for role in ["input", "output"]:
                apply_numeric_defaults(service[role], defaults)
        for schema in effective["model"]["events"].values():
            apply_numeric_defaults(schema, defaults)
    for row in effective["commands"]:
        target = row_target(row)
        require(isinstance(target, dict), "MAPPING_TARGET", "target必须是对象")
        kind, identifier = target.get("kind"), target.get("identifier")
        require(isinstance(identifier, str) and identifier, "MAPPING_TARGET", "target必须指定identifier")
        model = effective["model"]
        if kind == "service":
            require(identifier in model["methods"], "MODEL_PATH", "物模型中不存在服务：" + identifier)
            require(model["methods"][identifier].get("availability", "active") != "suspended" or row.get("availability") == "suspended", "COMMAND_SUSPENDED", "已停用的物模型服务不能配置为启用指令：" + identifier)
            row["method"] = identifier
            continue
        require(kind in {"property", "event"}, "MAPPING_TARGET", "target.kind只支持property、service、event")
        if kind == "property":
            require(identifier in model["properties"], "MODEL_PATH", "物模型中不存在属性：" + identifier)
            field = model["properties"][identifier]
            access, behavior = field.get("access"), target.get("behavior")
            require(access in {"r", "w", "rw"}, "PROPERTY_ACCESS", "属性必须声明access为r、w或rw")
            require(behavior in {"read", "write", "report"}, "MAPPING_TARGET", "属性映射须声明read、write或report")
            require((behavior != "write" or "w" in access) and (behavior not in {"read", "report"} or "r" in access), "PROPERTY_ACCESS", "映射行为不符合属性读写权限")
            value = object_schema({identifier: copy.deepcopy(field)})
            input_schema = value if behavior == "write" else object_schema()
            output_schema = value if "incoming" in row["receive_variants"].split("|") else object_schema()
            require((behavior != "report" or row["interaction"] == "receive_only") and (behavior != "read" or row["interaction"] != "receive_only"), "DIRECTION_INVALID", "属性行为与交互方式不一致")
            require(behavior == "write" or "incoming" in row["receive_variants"].split("|"), "DIRECTION_INVALID", "读取或上报属性必须定义返回的属性数据")
        else:
            require(identifier in model["events"], "MODEL_PATH", "物模型中不存在事件：" + identifier)
            require(row["interaction"] == "receive_only", "DIRECTION_INVALID", "事件映射只能上行")
            input_schema, output_schema = object_schema(), copy.deepcopy(model["events"][identifier])
        internal = "__ble_" + row["operation"]
        require(internal not in model["methods"], "MODEL_PATH", "内部适配名称与服务冲突")
        model["methods"][internal] = {"name": target_reference(target), "input": input_schema, "output": output_schema}
        row["method"] = internal
    return effective


def import_pair(model, mapping, blank, model_text=None):
    require(isinstance(model, dict), "MODEL_SCHEMA", "物模型必须是JSON对象")
    if isinstance(mapping, dict) and mapping.get("format") == "ble-mapping-definition/1.0":
        from ble_split_definition import migrate
        model, mapping = migrate(model, mapping, model_text)
    actual = mapping.get("format") if isinstance(mapping, dict) else None
    require(actual == FORMAT, "MAPPING_FORMAT", f"收到格式{actual!r}；当前标准为{FORMAT}，另支持ble-mapping-definition/1.0的显式迁移")
    # Only the original bare demo examples may omit system-generated metadata.
    # Versioned models/new semantics cannot bypass association by deleting it.
    if "modelRef" not in mapping and "requiredCapabilities" not in mapping and isinstance(model, dict) and not has_platform_types(model) and set(model) <= {"properties", "services", "methods", "events"} and set(mapping) <= {"format", "commands", "identity"} and isinstance(mapping.get("commands"), list) and all(isinstance(c, dict) and not (set(c) & COMMAND_METADATA) for c in mapping["commands"]):
        mapping = copy.deepcopy(mapping)
