        mapping["requiredCapabilities"] = sorted(required_capabilities(model, mapping))
        mapping["provenance"] = {"legacyImport": "bare-v1-no-model-identity"}
    validate_schema(mapping, "ble-thing-mapping.schema.json", "MAPPING_FORMAT")
    require(not (set(mapping.get("requiredCapabilities", [])) - CAPABILITIES), "CONSUMER_CAPABILITY", "消费者不支持所声明能力：" + ", ".join(sorted(set(mapping.get("requiredCapabilities", [])) - CAPABILITIES)))
