    require(not missing, "CONSUMER_CAPABILITY", "映射漏报必要能力：" + ", ".join(sorted(missing)))
    ref = mapping.get("modelRef")
    if ref:
        require(all(k not in model or k in ref for k in ["id", "version"]), "MODEL_REFERENCE", "模型带有ID/版本时，映射必须明确引用同一ID/版本")
        for key in ["id", "version"]:
            require(key not in ref or ref[key] == model.get(key), "MODEL_REFERENCE", "映射关联的物模型" + key + "不匹配")
        require(ref["sha256"] == model_hash(model), "MODEL_REFERENCE", "物模型内容SHA256不匹配，请使用同次导出的两个文件")
    workspace = blank()
    workspace["model"] = normalize_model(model)
    workspace["model_metadata"] = model_metadata(model)
    workspace["mapping_metadata"] = {k: copy.deepcopy(v) for k, v in mapping.items() if k not in {"commands", "format", "modelRef"}}
    workspace["command_metadata"] = {}
    seen = set()
    commands = mapping.get("commands")
    require(isinstance(commands, list) and 0 < len(commands) <= 2000, "MAPPING_FORMAT", "commands必须是非空数组，最多2000条")
    for command in commands:
        allowed = {"id", "sid", "cid", "target", "interaction", "receiveVariants", "correlation", "timeoutMs", "source", "availability", "request", "incoming", "constraints", *COMMAND_METADATA}
        require(isinstance(command, dict) and not (set(command) - allowed), "MAPPING_FORMAT", "指令包含未支持的字段")
        op, target = command.get("id"), command.get("target")
        require(isinstance(op, str) and op.isidentifier() and op.isascii(), "MAPPING_FORMAT", "指令id必须是英文标识符")
        require(op not in seen, "COMMAND_DUPLICATE", "指令id重复")
        require(isinstance(target, dict), "MAPPING_TARGET", "每条指令必须指定target")
        require(set(target) <= {"kind", "identifier", "behavior"}, "MAPPING_TARGET", "target存在未支持字段")
        variants = command.get("receiveVariants")
        require(isinstance(variants, list) and all(isinstance(v, str) for v in variants), "INTERACTION_INVALID", "必须明确receiveVariants；没有应用回包时填写空数组")
        row = dict.fromkeys(codec.COMMAND_COLUMNS, "")
        require(target.get("kind") in {"property", "service", "event"} and isinstance(target.get("identifier"), str), "MAPPING_TARGET", "target必须指定合法kind和identifier")
        row.update(operation=op, method=target_reference(target), sid=command.get("sid"), cid=command.get("cid"), interaction=command.get("interaction"), receive_variants="|".join(variants), correlation=command.get("correlation", "none"), timeout_ms="" if command.get("timeoutMs") is None else str(command["timeoutMs"]), source=command.get("source", ""), availability=command.get("availability", "active"))
        require(all(isinstance(v, str) for v in row.values()), "MAPPING_FORMAT", "SID/CID须为HEX字符串，指令字段类型不正确")
        workspace["commands"].append(row)
        workspace["command_metadata"][op] = {k: copy.deepcopy(command[k]) for k in COMMAND_METADATA if k in command}
        seen.add(op)
        for role in ["request", "incoming"]:
            fields = command.get(role, [])
            require(isinstance(fields, list), "MAPPING_FORMAT", role + "必须是字段数组")
            for field in fields:
                allowed_fields = {"field", "tlv", "wireType", "required", "scale", "offset", "maxBytes", "length"}
                require(isinstance(field, dict) and not (set(field) - allowed_fields), "MAPPING_FORMAT", "字段映射包含未支持内容")
                require(all(isinstance(field.get(k), str) for k in ["field", "tlv", "wireType"]), "MAPPING_FORMAT", "字段必须声明field、tlv和wireType")
                require(type(field.get("required", True)) is bool, "MAPPING_FORMAT", "required必须为布尔值")
                if "length" in field:
                    wire = field["wireType"]
                    expected = codec.NUM[wire][1] if wire in codec.NUM else 1 if wire == "bool" else None
                    require(type(field["length"]) is int and field["length"] == expected, "VALUE_WIDTH", "固定类型的length必须与编码宽度一致；变长字段请用maxBytes")
                values = [op, role, field["tlv"], field["field"], field["wireType"], "M" if field.get("required", True) else "O", str(field.get("scale", "")), str(field.get("offset", "")), str(field.get("maxBytes", ""))]
                workspace["bindings"].append(dict(zip(codec.BINDING_COLUMNS, values)))
        for group in command.get("constraints", []):
            require(isinstance(group, dict) and set(group) == {"role", "container", "rule", "fields"} and isinstance(group["fields"], list), "GROUP_INVALID", "约束格式不正确")
            workspace["groups"].append(dict(zip(codec.GROUP_COLUMNS, [op, group["role"], group["container"], group["rule"], "|".join(group["fields"])])))
    validate_business_bindings(workspace)
    # Identity is assigned by the demo system; imported metadata is not device proof.
    return workspace


def export_pair(workspace):
    commands = []
    for row in workspace["commands"]:
        op = row["operation"]
        command = {"id": op, "target": row_target(row), "sid": row["sid"], "cid": row["cid"], "interaction": row["interaction"], "receiveVariants": row["receive_variants"].split("|") if row["receive_variants"] else [], "correlation": row["correlation"], "source": row["source"], "availability": row.get("availability") or "active"}
        if row["timeout_ms"]:
            command["timeoutMs"] = int(row["timeout_ms"])
        for role in ["request", "incoming"]:
            fields = []
            for field in workspace["bindings"]:
                if field["operation"] != op or field["role"] != role:
                    continue
                item = {"field": field["model_path"], "tlv": field["tlv_path"], "wireType": field["wire_type"], "required": field["required"] == "M"}
                for old, new in [("scale", "scale"), ("offset", "offset"), ("max_bytes", "maxBytes")]:
                    if field[old] != "":
                        item[new] = field[old]
                fields.append(item)
            if fields:
                command[role] = fields
        groups = [{"role": g["role"], "container": g["container_path"], "rule": g["rule"], "fields": g["fields"].split("|")} for g in workspace["groups"] if g["operation"] == op]
        if groups:
            command["constraints"] = groups
        command.update(copy.deepcopy(workspace.get("command_metadata", {}).get(op, {})))
        commands.append(command)
    model = {**copy.deepcopy(workspace.get("model_metadata", {})), **public_model(workspace["model"])}
    mapping = {**copy.deepcopy(workspace.get("mapping_metadata", {})), "format": FORMAT, "commands": commands}
    capabilities = set(mapping.get("requiredCapabilities", [])) | required_capabilities(model, mapping)
    model_text = json_text(model)
    mapping["modelRef"] = {**{k: model[k] for k in ["id", "version"] if k in model}, "sha256": model_hash(model)}
    capabilities.add("model-reference/1")
    mapping["requiredCapabilities"] = sorted(capabilities)
    return {"model": model, "mapping": mapping, "modelText": model_text, "mappingText": json_text(mapping)}


def business_shape(schema):
    """Descriptions and access are annotations; all data constraints must agree."""
    return {k: ({name: business_shape(child) for name, child in v.items()} if k == "properties" else business_shape(v) if k == "items" else copy.deepcopy(v)) for k, v in schema.items() if k not in {"title", "description", "access"}}


def validate_business_bindings(workspace):
    effective = prepare(workspace)
    model = effective["model"]
    rows = {c["operation"]: c for c in effective["commands"]}
    require(set(workspace.get("command_metadata", {})) <= set(rows), "MAPPING_TARGET", "业务映射引用了不存在的指令")
    for op, meta in workspace.get("command_metadata", {}).items():
        require(isinstance(meta, dict) and set(meta) <= COMMAND_METADATA, "MAPPING_TARGET", "指令附加定义存在未知字段")
        updates = meta.get("propertyUpdates", [])
        if updates:
            require("incoming" in rows[op]["receive_variants"].split("|"), "DIRECTION_INVALID", "属性更新只能绑定上行数据布局")
        if "resultSuccessCode" in meta:
            require("result" in rows[op]["receive_variants"].split("|"), "RESULT_FORMAT", "成功码仅适用于声明result的指令")
        seen = set()
        for update in updates:
            require(isinstance(update, dict) and set(update) == {"from", "to"}, "MAPPING_TARGET", "属性更新须明确from和to")
            target = update["to"]
            require("[]" not in update["from"], "MODEL_PATH", "属性更新from只支持对象路径；数组须整体投影")
            require(target in model["properties"] and target not in seen, "MODEL_PATH", "属性更新目标不存在或重复：" + str(target))
            seen.add(target)
            source = codec.schema_at(codec.role_schema(model, rows[op], "incoming"), update["from"])
            destination = model["properties"][target]
            require(destination.get("access") != "w", "PROPERTY_ACCESS", "上行数据不能更新只写属性")
            require(business_shape(source) == business_shape(destination), "TYPE_MISMATCH", "属性更新源与目标的数据结构或约束不一致：" + target)


def project(workspace, operation, direction, data, metadata):
    """Return a patch, not persisted state or a claim of request completion."""
    row = next(c for c in workspace["commands"] if c["operation"] == operation)
    target = row_target(row)
    result = {"properties": {}, "services": {}, "events": {}}
    if metadata.get("kind") in {"protocol_result", "empty_reply"}:
        return result
    kind, name = target["kind"], target["identifier"]
    if kind == "property":
        result["properties"] = copy.deepcopy(data)
    elif kind == "event":
        result["events"][name] = copy.deepcopy(data)
    else:
        result["services"][name] = {"input" if direction == "down" else "output": copy.deepcopy(data)}
    if direction == "up":
        for update in workspace.get("command_metadata", {}).get(operation, {}).get("propertyUpdates", []):
            value, present = data, True
            for token in update["from"].split("."):
                require("[]" not in token, "MODEL_PATH", "属性更新from只支持对象路径；数组须整体投影")
                if not isinstance(value, dict) or token not in value:
                    present = False
                    break
                value = value[token]
            if present:
                result["properties"][update["to"]] = copy.deepcopy(value)
    return result


def check_compiled_exchange(dictionary):
    """A cached codec tree cannot contradict its attached canonical sources."""
    pair = dictionary["exchange"]
    require(isinstance(pair, dict) and set(pair) == {"model", "mapping"}, "DICTIONARY_INVALID", "编译缓存exchange必须包含model和mapping")
    def blank():
        return {"format": "ble-codec-workspace/1", "model": {}, "commands": [], "bindings": [], "groups": []}
    workspace = import_pair(pair["model"], pair["mapping"], blank)
    effective = prepare(workspace)
    require(effective["model"] == dictionary["thing_model"], "DICTIONARY_INVALID", "编译缓存物模型与两文件定义不一致")
    rows = {r["operation"]: r for r in effective["commands"]}
    require(set(rows) == set(dictionary["commands"]), "DICTIONARY_INVALID", "编译缓存指令集合不一致")
    for op, row in rows.items():
        cmd = dictionary["commands"][op]
        expected = dict(row)
        expected.update(sid=int(row["sid"],16), cid=int(row["cid"],16), receive_variants=row["receive_variants"].split("|") if row["receive_variants"] else [], timeout_ms=int(row["timeout_ms"]) if row["timeout_ms"] else None)
        require(all(cmd.get(k, "active" if k == "availability" else None) == v for k, v in expected.items()), "DICTIONARY_INVALID", "编译缓存指令信息不一致：" + op)
        actual_fields, actual_groups = [], []
        def walk(nodes, role, parent=""):
            for n in nodes:
                path = (parent + "/" if parent else "") + f"{n['type_id']:02X}"
                actual_fields.append((role, path, n["model_path"], n["wire_type"], n["required"], codec.number(n["scale"],1), codec.number(n["offset"],0), n["max_bytes"]))
                actual_groups.extend((role, path, g["rule"], tuple(g["fields"])) for g in n["groups"])
                walk(n["children"], role, path)
        for role, nodes in cmd["layouts"].items():
            walk(nodes, role)
        expected_fields = [(r["role"], "/".join(f"{x:02X}" for x in codec.path_parts(r["tlv_path"])), r["model_path"], r["wire_type"], r["required"] == "M", codec.number(r["scale"],1), codec.number(r["offset"],0), int(r["max_bytes"]) if r["max_bytes"] != "" else None) for r in workspace["bindings"] if r["operation"] == op]
        expected_groups = [(r["role"], "/".join(f"{x:02X}" for x in codec.path_parts(r["container_path"])), r["rule"], tuple(r["fields"].split("|"))) for r in workspace["groups"] if r["operation"] == op]
        require(sorted(actual_fields) == sorted(expected_fields) and sorted(actual_groups) == sorted(expected_groups), "DICTIONARY_INVALID", "编译缓存字段或约束与两文件定义不一致：" + op)

