#!/usr/bin/env python3
"""Local BLE application-PDU codec workbench. No cloud or Bluetooth execution."""
from __future__ import annotations

import argparse
import copy
import csv
import hashlib
import io
import json
from pathlib import Path
import subprocess
import sys
import tempfile
from urllib.parse import urlsplit

import ble_protocol_mapping as codec
import ble_thing_mapping as thing_mapping

ROOT = Path(__file__).resolve().parents[1]
WORKSPACE_FORMAT = "ble-codec-workspace/1"
COLUMNS = {"commands": codec.COMMAND_COLUMNS, "bindings": codec.BINDING_COLUMNS, "groups": codec.GROUP_COLUMNS}
WIRE_TYPES = ["group", "array", "object", "repeated_object", *codec.NUM, "bool", "utf8", "bytes", *[t + "[]" for t in codec.NUM]]
MAX_BODY = 2 * 1024 * 1024


def text(path):
    raw = subprocess.check_output(["/bin/cat", str(path)]) if sys.platform == "darwin" else Path(path).read_bytes()
    return raw.decode("utf-8-sig", errors="strict")


def require(ok, code, message):
    codec.require(ok, code, message)


def blank():
    return {"format": WORKSPACE_FORMAT, "model": {"properties": {}, "methods": {}, "events": {}}, "commands": [], "bindings": [], "groups": []}


def signature(workspace):
    payload = {k: workspace[k] for k in ["model", "commands", "bindings", "groups"]}
    if "targets" in workspace:
        payload["targets"] = workspace["targets"]
    for key in ["model_metadata", "mapping_metadata", "command_metadata"]:
        if key in workspace:
            payload[key] = workspace[key]
    return hashlib.sha256(json.dumps(payload, ensure_ascii=False, sort_keys=True, allow_nan=False).encode()).hexdigest()


def validate_workspace(workspace):
    require(isinstance(workspace, dict) and workspace.get("format") == WORKSPACE_FORMAT, "WORKSPACE_FORMAT", "请上传ble-codec-workspace/1格式的工作区")
    model = workspace.get("model")
    require(isinstance(model, dict) and set(model) == {"properties", "methods", "events"}, "MODEL_SCHEMA", "物模型必须包含properties、methods、events三个对象")
    require(all(isinstance(model[k], dict) for k in model), "MODEL_SCHEMA", "物模型的属性、方法、事件必须是对象")
    for name, method in model["methods"].items():
        require(isinstance(method, dict) and "input" in method and "output" in method, "MODEL_SCHEMA", f"方法{name}必须明确输入input和输出output")
        for role in ["input", "output"]:
            schema = method[role]
            require(isinstance(schema, dict) and schema.get("type") == "object", "MODEL_SCHEMA", f"方法{name}的{role}必须是对象")
            codec.check_schema_subset(schema)
    for name, schema in model["properties"].items():
        codec.check_schema_subset(schema)
    for name, schema in model["events"].items():
        codec.check_schema_subset(schema)
    require(isinstance(workspace.get("targets", {}), dict), "MAPPING_TARGET", "targets必须是对象")
    for key, columns in COLUMNS.items():
        rows = workspace.get(key)
        require(isinstance(rows, list) and len(rows) <= 2000, "TABLE_SHAPE", f"{key}必须是最多2000行的表格")
        for index, row in enumerate(rows):
            if key == "commands" and isinstance(row, dict) and set(row) == set(columns[:-1]):
                row["availability"] = "active"
            require(isinstance(row, dict) and set(row) == set(columns) and all(isinstance(v, str) for v in row.values()), "TABLE_SHAPE", f"{key}第{index + 1}行列不匹配（缺少：{sorted(set(columns)-set(row)) if isinstance(row,dict) else columns}；多余：{sorted(set(row)-set(columns)) if isinstance(row,dict) else []}），所有值须为字符串")
    return workspace


def system_identity(workspace):
    digest = signature(workspace)
    original = workspace.get("identity")
    if isinstance(original, dict) and workspace.get("source_signature") == digest:
        return copy.deepcopy(original)
    return {"product_id": "LOCAL_CODEC_EXPERIMENT", "firmware_version": "DEMO_NOT_REAL_FIRMWARE", "function_version": "demo-model-" + digest[:12], "dictionary_version": "demo-dictionary-" + digest[:12], "transport_ref": "application-pdu-only-no-gatt"}


def compile_workspace(workspace):
    validate_workspace(workspace)
    thing_mapping.normalize_model({**workspace.get("model_metadata", {}), **thing_mapping.public_model(workspace["model"])})
    thing_mapping.validate_business_bindings(workspace)
    require(workspace["commands"], "DICTIONARY_MISSING", "还没有指令字典：请上传字典或逐行新增指令和绑定")
    effective = thing_mapping.prepare(workspace)
    with tempfile.TemporaryDirectory(prefix="ble-codec-workspace-") as temp:
        folder = Path(temp)
        (folder / "thing-model.json").write_text(json.dumps(effective["model"], ensure_ascii=False), encoding="utf-8")
        (folder / "product.system.json").write_text(json.dumps(system_identity(workspace), ensure_ascii=False), encoding="utf-8")
        for key, columns in COLUMNS.items():
            with (folder / (key + ".csv")).open("w", newline="", encoding="utf-8") as f:
                writer = csv.DictWriter(f, fieldnames=columns)
                writer.writeheader()
                writer.writerows(effective[key])
        dictionary = codec.compile_tables(folder)
    exported = thing_mapping.export_pair(workspace)
    dictionary["exchange"] = {k: exported[k] for k in ["model", "mapping"]}
    codec.check_snapshot(dictionary, dictionary["identity"])
    return dictionary


def operation_descriptions(dictionary):
    return [{"operation": op, "method": dictionary["thing_model"]["methods"][c["method"]].get("name", c["method"]) if c["method"].startswith("__ble_") else c["method"], "sid": c["sid"], "cid": c["cid"], "interaction": c["interaction"], "request_schema": dictionary["thing_model"]["methods"][c["method"]]["input"], "incoming_schema": dictionary["thing_model"]["methods"][c["method"]]["output"], "availability": c.get("availability", "active"), "can_encode_down": c.get("availability", "active")=="active" and "request" in c["layouts"], "can_encode_up": c.get("availability", "active")=="active" and "incoming" in c["layouts"]} for op, c in dictionary["commands"].items()]


def dictionary_to_workspace(dictionary):
    require(isinstance(dictionary, dict), "DICTIONARY_INVALID", "机器字典必须是JSON对象")
    codec.check_snapshot(dictionary, dictionary.get("identity"))
    if "exchange" in dictionary:
        pair = dictionary["exchange"]
        workspace = thing_mapping.import_pair(pair["model"], pair["mapping"], blank)
        workspace["identity"] = copy.deepcopy(dictionary["identity"])
        workspace["source_signature"] = signature(workspace)
        rebuilt = compile_workspace(workspace)
        require(rebuilt["commands"] == {op: {"availability": "active", **c} for op, c in dictionary["commands"].items()}, "IMPORT_UNREPRESENTABLE", "编译缓存与随附两文件定义不一致")
        return workspace
    workspace = blank()
    workspace["model"] = copy.deepcopy(dictionary["thing_model"])
    workspace["identity"] = copy.deepcopy(dictionary["identity"])
    for op, cmd in dictionary["commands"].items():
        row = {key: "" for key in codec.COMMAND_COLUMNS}
        row.update(availability=cmd.get("availability", "active"), operation=op, method=cmd["method"], sid=f'{cmd["sid"]:02X}', cid=f'{cmd["cid"]:02X}', interaction=cmd["interaction"], receive_variants="|".join(cmd["receive_variants"]), correlation=cmd["correlation"], timeout_ms="" if cmd["timeout_ms"] is None else str(cmd["timeout_ms"]), source=cmd["source"])
        workspace["commands"].append(row)

        def walk(nodes, role, prefix=""):
            for node in nodes:
                path = (prefix + "/" if prefix else "") + f'{node["type_id"]:02X}'
                workspace["bindings"].append(dict(zip(codec.BINDING_COLUMNS, [op, role, path, node["model_path"], node["wire_type"], "M" if node["required"] else "O", node["scale"], node["offset"], "" if node["max_bytes"] is None else str(node["max_bytes"])])))
                for group in node["groups"]:
                    workspace["groups"].append(dict(zip(codec.GROUP_COLUMNS, [op, role, path, group["rule"], "|".join(group["fields"])])))
                walk(node["children"], role, path)
        for role, nodes in cmd["layouts"].items():
            walk(nodes, role)
    validate_workspace(workspace)
    workspace["source_signature"] = signature(workspace)
    # Recompile reconstructed tables: don't accept an import we cannot reproduce.
    rebuilt = compile_workspace(workspace)
    require(rebuilt["commands"] == {op: {"availability": "active", **cmd} for op, cmd in dictionary["commands"].items()}, "IMPORT_UNREPRESENTABLE", "导入字典无法无损还原为当前支持的表格，请核对其格式")
    return workspace


def parse_csv(source, columns):
    reader = csv.DictReader(io.StringIO(source.lstrip("\ufeff"), newline=""))
    legacy = columns == codec.COMMAND_COLUMNS and reader.fieldnames == columns[:-1]
    require(reader.fieldnames == columns or legacy, "CSV_HEADER", "CSV表头必须为：" + ",".join(columns))
    rows = list(reader)
    if legacy:
        for row in rows: row["availability"] = "active"
    require(all(None not in row and all(v is not None for v in row.values()) for row in rows), "CSV_SHAPE", "CSV存在多余列或缺少单元格")
    return rows


def import_content(request):
    kind, source = request.get("kind"), request.get("text")
    require(isinstance(source, str), "IMPORT_TEXT", "请选择UTF-8文本文件")
    if kind == "pair":
        require(isinstance(request.get("modelText"), str), "MODEL_MISSING", "请选择对应的物模型JSON")
        workspace = thing_mapping.import_pair(json.loads(request["modelText"].lstrip("\ufeff")), json.loads(source.lstrip("\ufeff")), blank, request["modelText"])
        compile_workspace(workspace)
    elif kind == "workspace":
        workspace = json.loads(source.lstrip("\ufeff"))
        validate_workspace(workspace)
    elif kind == "dictionary":
        workspace = dictionary_to_workspace(json.loads(source.lstrip("\ufeff")))
    else:
        workspace = copy.deepcopy(request.get("workspace") or blank())
        validate_workspace(workspace)
        if kind == "model":
            parsed = json.loads(source.lstrip("\ufeff"))
            workspace["model"] = thing_mapping.normalize_model(parsed)
            workspace["model_metadata"] = thing_mapping.model_metadata(parsed)
        else:
            require(kind in COLUMNS, "IMPORT_KIND", "未知上传类型")
            workspace[kind] = parse_csv(source, COLUMNS[kind])
        validate_workspace(workspace)
    return {"ok": True, "workspace": workspace}


def load_example(name):
    folder = ROOT / "examples/app-protocol-mapping-v1" / name
    workspace = blank()
    workspace["model"] = json.loads(text(folder / "thing-model.json"))
    for key, columns in COLUMNS.items():
        workspace[key] = parse_csv(text(folder / (key + ".csv")), columns)
    return workspace


