def parse_hex(source):
    require(isinstance(source, str), "FRAME_HEX", "请输入HEX字符串")
    try:
        frame = bytes.fromhex(source)
    except ValueError:
        raise codec.MappingError("FRAME_HEX", "HEX只能包含成对的十六进制数字及空白，例如80 01 06 01 05")
    require(2 <= len(frame) <= codec.MAX_PDU, "PDU_LENGTH", "完整应用PDU须为2～2048字节，包含SID/CID")
    return frame


def convert(request):
    dictionary = compile_workspace(request.get("workspace"))
    direction, mode, operation = request.get("direction"), request.get("mode"), request.get("operation")
    require(direction in {"down", "up"} and mode in {"encode", "decode"}, "MODE_INVALID", "请选择上行／下行以及编码／解码")
    if mode == "decode":
        frame = parse_hex(request.get("hex"))
        if operation == "auto":
            matches = [op for op, c in dictionary["commands"].items() if (c["sid"], c["cid"]) == tuple(frame[:2])]
            require(len(matches) == 1, "COMMAND_UNKNOWN", f"字典没有唯一匹配的SID/CID：{frame[0]:02X}/{frame[1]:02X}")
            operation = matches[0]
    require(operation in dictionary["commands"], "COMMAND_UNKNOWN", "请先选择已配置的指令；编码不能使用自动识别")
    identity = dictionary["identity"]
    if mode == "encode":
        frame = codec.encode(dictionary, operation, "request" if direction == "down" else "incoming", request.get("data"), identity)
    if direction == "down":
        model_json = codec.decode_request(dictionary, operation, frame, identity)
        metadata = {"kind": "request", "note": "仅完成应用PDU转换，没有发送到设备"}
    else:
        decoded = codec.decode(dictionary, operation, frame, identity)
        model_json = decoded.pop("data")
        metadata = decoded
        if metadata["kind"] in {"empty_reply", "protocol_result"}:
            metadata["note"] = "该消息不含物模型字段；结果码或空回包信息单独展示，不补造业务数据"
    extra = request["workspace"].get("command_metadata", {}).get(operation, {})
    if metadata.get("kind") == "protocol_result" and "resultSuccessCode" in extra:
        metadata["success"] = metadata["result_code"] == extra["resultSuccessCode"]
        metadata["success_code_source"] = "dictionary"
    projected = thing_mapping.project(request["workspace"], operation, direction, model_json, metadata)
    return {"ok": True, "operation": operation, "direction": direction, "hex": frame.hex(" ").upper(), "byte_length": len(frame), "bits": " ".join(f"{b:08b}" for b in frame), "model_json": model_json, "thing_model_json": projected, "metadata": metadata, "dictionary": dictionary}
